"""Render the larger AMI batch with distinct-question counts and clear review status."""
from html import escape as e
import json
from pathlib import Path
from site_navigation import project_tabs,experiment_subtabs
from ami_pipeline import study_roles
ROOT=Path(__file__).resolve().parents[1];D=ROOT/'research/question-scale'
def read(name):return json.loads((D/name).read_text())
TOPICS={'EN2001b':'Meeting-browser development','EN2004a':'Transcription guidelines','EN2009b':'Eye-tracking annotation software','IN1005':'Webpage topic models','IN1007':'Keyword-spotting research','IB4001':'Office-allocation role-play','IB4003':'Office-allocation role-play','EN2006b':'Astronomy annotation guidelines'}
def clock(t):return f'{int(t)//60}:{int(t)%60:02d}'
def p(text):return '<p>'+e(str(text))+'</p>'
def table(n,title,headers,rows):return '<div class="table-wrap"><table><caption>Table '+str(n)+'. '+e(title)+'</caption><thead><tr>'+''.join('<th scope="col">'+e(str(h))+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+e(str(v))+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def hist(values,bins,unit):
 counts=[sum(a<=v<(b if i<len(bins)-2 else b+1e-6) for v in values) for i,(a,b) in enumerate(zip(bins,bins[1:]))];maximum=max(counts) or 1
 return '<ul class="histogram">'+''.join('<li><span>'+e(f'{a:g}–{b:g} {unit}')+'</span><span class="bar-space"><span class="bar" style="width:'+str(100*n/maximum)+'%"></span></span><b>'+str(n)+'</b></li>' for a,b,n in zip(bins,bins[1:],counts))+'</ul>'
def card(q,alternative=False):
 evidence=''.join('<li><strong>'+e(c['speaker'])+'</strong> · '+clock(c['start'])+'–'+clock(c['end'])+p(c['text'])+'</li>' for c in q['evidence'])
 full=q.get('full_history_check');recent=q.get('recent_minute_check');controls=''
 controls+=p('Original model proposed answer: '+q['generator_proposed_answer'])
 if q.get('edited'):controls+=p('Reader checks used the original model draft: '+q['generator_question'])
 if full:controls+='<h4>Full-history reader</h4>'+p(full['answer'])+p('Missing information: '+(full['missing_information'] or 'None reported.'))
 if recent and recent['invalid_ids']:controls+=p('Reader cited unavailable passages: '+', '.join(recent['invalid_ids']))
 if recent:controls+='<h4>Reader with only the latest minute</h4>'+p(recent['answer'])+p('Missing information: '+(recent['missing_information'] or 'None reported.'))
 content='<article class="card scale-question'+(' alternative' if alternative else '')+'" id="'+e(q['id'])+'" data-meeting="'+e(q['meeting'])+'" data-time="'+q['cohort']+'"><h3>'+e(q['meeting']+' · '+clock(q['at'])+' · '+f"{q['percent']:.1f}% elapsed")+'</h3><p class="question">'+e(q['question'])+'</p>'+p('Requester '+q['requester']+(' · '+q['role'] if q['role'] else ' · perspective inferred from earlier speech')+' · Written by Qwen3 30B Instruct'+(' with Codex edits' if q.get('edited') else ''))+p('Why ask now: '+q['why_now'])+p('Codex review: '+q['codex_review'])+'<details><summary>Source support and reader checks</summary><p><strong>Evaluation reference:</strong> '+e(q['reference_answer'])+'</p><ul>'+evidence+'</ul>'+controls+'</details>'
 if q.get('alternatives'):content+='<details><summary>Alternative phrasing or later repeat of this question ('+str(len(q['alternatives']))+')</summary>'+''.join(card(a,True) for a in q['alternatives'])+'</details>'
 return content+'</article>'
def main():
 s=read('status.json');questions=read('questions.json')['questions'];timing=read('timing.json');meetings=read('meetings.json');complete=s['codex_review_complete'];summary=s['summary']
 body='<header class="site-nav"><div class="nav-inner"><a class="brand" href="../index.html">AI2AI Duplex</a>'+project_tabs('experiments','../')+'</div></header><div class="container">'+experiment_subtabs('ami')+'</div><main id="main"><div class="container"><header class="hero"><span class="eyebrow">Larger AMI question batch</span><h1>More questions from more meetings</h1><p class="lede">Twenty additional meetings add new discussions, requester voices and earlier question times. The existing 43-question pilot and its audio remain available.</p><p><a href="question-pilot.html">Earlier question and audio pilot</a> · <a href="#questions">Review new questions</a></p></header>'
 body+='<section class="section" id="progress"><h2>Batch progress</h2>'+p(('Codex has completed the source review.' if complete else 'Generation and source review are in progress. Drafts are not counted as accepted questions.'))+'<dl class="metrics">'+''.join('<div><dt>'+e(label)+'</dt><dd>'+e(str(value))+'</dd></div>' for label,value in [('Additional meetings',20),('Available transcript cutoffs',s['ready_windows']),('Model drafts generated',s['drafts']),('Distinct questions retained',s['retained_distinct'] if complete else 'Awaiting Codex review')])+'</dl>'
 stages=[('Generate candidate questions',s['drafts']>0,summary is not None),('Check source support and naturalness with the local model',s['full_history_reviews']>0,summary is not None),('Review questions and duplicate groups with Codex',s['codex_reviewed']>0,complete),('Publish reviewed questions and timing statistics',complete,complete)]
 body+='<ol>'+''.join('<li><strong>'+('Done' if done else 'In progress' if started else 'To do')+' · '+e(label)+'</strong></li>' for label,started,done in stages)+'</ol>'+p('Job '+s['job']+'. '+str(s['gpus_per_job'])+' GPU per job; '+s['gpu_type_vram']+'. '+s['gpu_role']+' Maximum one GPU active. Report preparation and publication use zero GPUs.')+'</section>'
 body+='<section class="section" id="method"><h2>How this batch works</h2>'+study_roles()+'<p>Earlier pilots depended heavily on Codex selecting evidence and writing comparison questions. This batch lets the local model work from the complete available transcript and generate up to three distinct questions at each cutoff. There is no question quota to fill when a useful request does not fit.</p><figure><ol class="modules">'
 modules=[('Prepare the history','Manual AMI transcript, word times, speaker labels and official roles where present.','All transcript excerpts released by the question time; no future speech.'),('Generate questions','Earlier history and naturalness instructions.','Up to three questions beginning “Assistant,”, with a requester, proposed answer and source IDs.'),('Check independently of the proposed answer','Only the question, requester and allowed earlier history; proposed answers and generator rationale are hidden.','A fresh answer, cited sources and checks of the premise, requester and naturalness. The same checkpoint runs both stages.'),('Compare context and remove duplicates','Questions that pass the model’s first checks; the latest minute; questions from the same meeting.','Recent-context answers and groups of questions asking for the same facts.'),('Review and retain','The questions, original source passages, model checks and duplicate groups.','Codex’s retain/exclude decisions. Distinct accepted questions are counted once; alternative phrasings and later repeats stay together.')]
 body+=''.join('<li><h3>'+e(title)+'</h3>'+p('Input: '+inputs)+p('Output: '+outputs)+'</li>' for title,inputs,outputs in modules)+'</ol><figcaption>Figure 1. Text-generation and review pipeline. No TTS or duplex-model inference is part of this batch.</figcaption></figure><p>A retained question must sound like a plausible request from that participant and use earlier history. Its premise must be supported, and its evaluation reference must preserve any missing information or uncertainty. Codex checks source passages rather than accepting a model’s approval flag. The recent-minute control includes complete transcript excerpts whose start falls within the last 60 seconds; an excerpt crossing the start boundary is omitted. Multiple citations or failure under this limited context do not prove multi-hop reasoning. Generation and automated screening use the same model; independent human ratings remain a separate step.</p></section>'
 if s.get('review_summary'):
  r=s['review_summary'];body+='<section class="section" id="review"><h2>What survived review?</h2>'+p(str(r['distinct_questions'])+' distinct questions remain, with '+str(r['alternative_records'])+' alternative phrasings or later repeats saved underneath them. Codex reviewed all 75 questions that passed the automated screen. This is AI review of the source, not an independent human rating.')
  body+=table(1,'Draft texts at each review stage. Counts refer to draft records, not distinct questions. A text excluded at an earlier stage does not enter the next stage.',['Stage','Draft texts considered','Texts kept for next stage','Why other drafts did not proceed'],[['Source-annotation checks',294,110,'184 drafts had missing or mismatched source IDs, requester evidence, or no cited fact older than 60 seconds. Some have more than one flag; each draft is counted once.'],['Local-model source and naturalness screen',110,75,'35 drafts were not approved for their premise, requester or spoken naturalness. The same checkpoint ran this check with proposed answers hidden. These 35 did not receive a full Codex source review.'],['Codex review against the transcript',75,44,'31 drafts asked for new advice, assumed an unrecorded decision, depended on missing visual information, repeated recent facts, or otherwise lacked a useful supported question.']])
  body+='<p>The 44 retained texts represent 40 distinct questions and four alternatives or later repeats. Counts group the requested facts within each meeting; using a similar request in another meeting creates another test instance. Nineteen of the 40 primary questions include Codex text edits; others needed corrections only to their evaluation reference. This is a reviewed development set, not an automatically accepted corpus. Cards identify Codex edits and preserve the model’s original question and proposed answer.</p><p>For example, one proposed answer confused a €50 million total-profit goal with a per-unit margin. Another placed an infrared sender near a hinge even though the cited speech only proposed the front of the bottom layer and said it had not been installed. The source review corrected those claims; fluent answers from two model calls were insufficient.</p></section>'
 body+='<section class="section" id="coverage"><h2>Which meetings and times?</h2><p>The selection covers new participant groups, technical discussions, annotation work, office planning and remote-control design. It deliberately varies topics and design stages; it is not a random sample. The new participant groups do not overlap with each other or the five earlier AMI meetings. Earlier sessions are never supplied as context for a later session.</p><p>Targets are five, seven-and-a-half and ten minutes, the midpoint and 80% of the meeting. The actual time uses a gap after completed speech, so some early targets move by several minutes. Actual times are listed below and used in all statistics. '+str(s['ready_windows'])+' of 100 prepared cutoffs fit the declared 49,152-token context with the output allowance; two long cutoffs were omitted, without truncating their history. Timing fractions use official AMI meeting durations.</p>'
 body+=table(2,'New meetings, full recording duration and usable question cutoffs. Times include recording setup and pauses.',['Meeting','Topic','Full duration','Actual question cutoffs'],[[m['id'],TOPICS.get(m['id'],'Remote-control design role-play'),clock(m['duration_seconds']),', '.join(clock(w['at']) for w in read('windows.json') if w['meeting']==m['id'])] for m in meetings])+'</section>'
 if timing:
  body+='<section class="section" id="timing"><h2>When are the retained questions inserted?</h2>'+p(f"The {timing['distinct_questions']} distinct questions have a mean insertion time of {timing['mean_minutes']:.2f} minutes, or {timing['mean_percent']:.2f}% of the full meeting. {timing['early_questions']} fall between 4:30 and 10:30 after the recording starts. Each question contributes once; alternative phrasings do not change the distribution.")+'<div class="plot-grid"><figure>'+hist(timing['minutes'],[0,5,7.5,10.5,20,30,45,70],'min')+'<figcaption>Figure 2. Elapsed time before insertion, counting each distinct question once.</figcaption></figure><figure>'+hist(timing['percentages'],[0,20,40,60,80,100],'%')+'<figcaption>Figure 3. Percentage of the full meeting elapsed at insertion.</figcaption></figure></div></section>'
 body+='<section class="section" id="questions"><h2>Reviewed questions</h2>'
 if questions:
  body+='<p>Each card is a distinct question. Expand it to inspect its original source speech and model reader answers. These are quality checks for question generation; spoken answer generation remains deferred.</p><label>Meeting <select id="meeting-filter"><option value="all">All meetings</option>'+''.join('<option>'+e(m)+'</option>' for m in sorted({q['meeting'] for q in questions}))+'</select></label><output id="question-count" aria-live="polite"></output><div class="questions">'+''.join(card(q) for q in questions)+'</div>'
 else:body+='<p>No draft is presented as accepted before Codex’s source review. The completed questions will appear here after that review.</p>'
 body+='</section><section class="section" id="resources"><h2>Model and resources</h2><p>Qwen3-30B-A3B-Instruct-2507 runs through vLLM 0.16.0 in BF16, with one GPU, a 49,152-token context, 8 GiB of KV cache, prefix caching, CUDA graphs and batches of up to four requests. One resident engine handles sequential generation and screening stages. No TTS model, voice encoder or duplex service shares the allocation.</p>'
 if summary:body+=p(f"The run generated {summary['drafts']} drafts and recorded {summary['blinded_reviews']} full-history checks and {summary['recent_controls']} recent-minute controls. Runtime: {summary['total_seconds']:.1f} seconds including model loading. Output: {summary['output_tokens']} tokens. Completion of inference does not by itself validate a question.")
 if s['accounting']:body+=p(f"Actual allocation: {s['accounting']['elapsed_seconds']} seconds / {s['accounting']['gpu_hours']:.4f} GPU hours. All text stages share GPU 0; maximum one GPU active.")
 body+='<p><a href="../research/question-scale/questions.json">Reviewed question data</a> · <a href="../research/question-scale/reviews.json">Codex decisions</a> · <a href="../research/question-scale/timing.json">Timing data</a> · <a href="../research/question-scale/status.json">Batch status</a> · <a href="https://groups.inf.ed.ac.uk/ami/corpus/">AMI corpus</a></p><p>The questions are synthetic. The original participants did not ask them. Text history comes from AMI’s manual annotations; the half-second transcript release delay is an assumption, not measured streaming ASR.</p></section></div></main>'
 css='''.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1rem}.metrics>div{padding:1rem;border:1px solid var(--border);border-radius:10px}.metrics dt{font-size:.9rem}.metrics dd{font-size:1.7rem;font-weight:700;margin:.4rem 0 0}.modules{padding-left:1.3rem}.modules li{margin:1.4rem 0}.question{font-size:1.13rem;font-weight:600}.questions{display:grid;gap:1.3rem;margin-top:1.5rem}.scale-question{min-width:0}.table-wrap{overflow-x:auto;max-width:100%}table{border-collapse:collapse;width:100%}caption{text-align:left;padding:1rem 0}th,td{padding:.7rem;border-bottom:1px solid var(--border);text-align:left;vertical-align:top}.plot-grid{display:grid;grid-template-columns:1fr 1fr;gap:1rem}figure{margin:1.5rem 0}figcaption{font-size:.9rem}.histogram{list-style:none;padding:0}.histogram li{display:grid;grid-template-columns:7rem 1fr 2rem;gap:.5rem;margin:.7rem 0}.bar-space{display:block;background:var(--surface);min-width:0}.bar{display:block;background:var(--accent);height:1.2rem}#question-count{display:block;margin:1rem 0}.scale-question[hidden]{display:none}select{max-width:100%}@media(max-width:700px){.metrics{grid-template-columns:1fr 1fr}.plot-grid{grid-template-columns:1fr}}@media(max-width:360px){.metrics{grid-template-columns:1fr}}'''
 js='''const filter=document.getElementById('meeting-filter');if(filter){const update=()=>{let n=0;for(const card of document.querySelectorAll('.scale-question:not(.alternative)')){card.hidden=filter.value!=='all'&&card.dataset.meeting!==filter.value;if(!card.hidden)n++;}document.getElementById('question-count').textContent=n+' distinct questions shown';};filter.addEventListener('change',update);update();}'''
 html='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="light dark"><meta name="description" content="A larger batch of natural meeting questions across twenty additional AMI meetings, with source review and distinct-question counts."><title>Larger AMI question batch · AI2AI Duplex</title><link rel="stylesheet" href="../assets/site.css"><style>'+css+'</style></head><body><a class="skip-link" href="#main">Skip to question batch</a>'+body+'<script>'+js+'</script></body></html>'
 (ROOT/'experiments/question-scale.html').write_text(html);print('Rendered larger batch:',s['drafts'],'drafts;',len(questions),'reviewed distinct questions.')
if __name__=='__main__':main()
